# Moxa ioLogik E1242 over Modbus/TCP (modbus-tcp, port 502): every channel of
# moxa-iologik-e1242.device. Addresses are 0-based PDU addresses, the manual's
# "Start Address (decimal)" column (ioLogik E1200 User's Manual v15.10,
# p. A-14), not its 1-based "Start Register". Not checked on a unit.
device e1242 modbus-tcp ADDR:502 unit=1 timeout_ms=300

# digital inputs: discrete inputs 0..7
in  e1242_di_00        bool e1242 di:0
in  e1242_di_01        bool e1242 di:1
in  e1242_di_02        bool e1242 di:2
in  e1242_di_03        bool e1242 di:3
in  e1242_di_04        bool e1242 di:4
in  e1242_di_05        bool e1242 di:5
in  e1242_di_06        bool e1242 di:6
in  e1242_di_07        bool e1242 di:7

# counters (counter mode; 0 in DI mode): input registers 16 + 2n, high word first
in  e1242_di_00_count  int  e1242 ir:16:u32
in  e1242_di_01_count  int  e1242 ir:18:u32
in  e1242_di_02_count  int  e1242 ir:20:u32
in  e1242_di_03_count  int  e1242 ir:22:u32
in  e1242_di_04_count  int  e1242 ir:24:u32
in  e1242_di_05_count  int  e1242 ir:26:u32
in  e1242_di_06_count  int  e1242 ir:28:u32
in  e1242_di_07_count  int  e1242 ir:30:u32

# digital outputs: coils 0..3
out e1242_do_00        bool e1242 coil:0 safe=false
out e1242_do_01        bool e1242 coil:1 safe=false
out e1242_do_02        bool e1242 coil:2 safe=false
out e1242_do_03        bool e1242 coil:3 safe=false

# what the unit says its outputs are: the coils read back
in  e1242_do_00_status bool e1242 coil:0
in  e1242_do_01_status bool e1242 coil:1
in  e1242_do_02_status bool e1242 coil:2
in  e1242_do_03_status bool e1242 coil:3

# analog inputs, raw value: input registers 512..515
in  e1242_ai_00_raw    int  e1242 ir:512
in  e1242_ai_01_raw    int  e1242 ir:513
in  e1242_ai_02_raw    int  e1242 ir:514
in  e1242_ai_03_raw    int  e1242 ir:515

# 0 normal, 1 burnout, 2 over range, 3 under range
in  e1242_ai_00_status int  e1242 ir:576
in  e1242_ai_01_status int  e1242 ir:577
in  e1242_ai_02_status int  e1242 ir:578
in  e1242_ai_03_status int  e1242 ir:579
